mapper.select:
SELECT COUNT(*)
FROM tb_order
WHERE shop_id = #{shopId}
  AND status = #{status}

SELECT COUNT(*)
FROM tb_order
WHERE sku_id = #{skuId}
  AND shop_id = #{shopId}

SELECT CAST(strftime('%H', pay_time) AS INTEGER) AS hour,
       SUM(total_price) AS amount
FROM tb_order
WHERE shop_id = #{shopId}
  AND pay_time >= #{dayStart}
  AND pay_time < #{dayEnd}
  AND status IN ('PAID', 'SHIPPED', 'COMPLETED')
GROUP BY strftime('%H', pay_time)

SELECT COUNT(*)
FROM tb_order
WHERE shop_id = #{shopId}
  AND pay_time >= #{dayStart}
  AND pay_time < #{dayEnd}
  AND status IN ('PAID', 'SHIPPED', 'COMPLETED')

SELECT COUNT(DISTINCT buyer_username)
FROM tb_order
WHERE shop_id = #{shopId}
  AND pay_time >= #{dayStart}
  AND pay_time < #{dayEnd}
  AND status IN ('PAID', 'SHIPPED', 'COMPLETED')

SELECT SUM(total_price)
FROM tb_order
WHERE shop_id = #{shopId}
  AND pay_time >= #{dayStart}
  AND pay_time < #{dayEnd}
  AND status IN ('PAID', 'SHIPPED', 'COMPLETED')

SELECT SUM(amount)
FROM tb_refund
WHERE shop_id = #{shopId}
  AND create_time >= #{dayStart}
  AND create_time < #{dayEnd}

