pay_type = #{payType}, pay_time = datetime('now', 'localtime'),
update_time = datetime('now', 'localtime') WHERE id = #{id}

mapper.select:
SELECT id, order_no, shop_id, sku_id, sku_name, quantity, total_price,
       status, pay_type, pay_time, receiver_name, receiver_phone, receiver_address,
       buyer_username, logistics_no, logistics_type, create_time, update_time
FROM tb_order
WHERE id = #{id}
  AND shop_id = #{shopId}

mapper.update:
UPDATE tb_order
SET status = #{status},
    update_time = datetime('now', 'localtime')
WHERE id = #{id}
  AND shop_id = #{shopId}

UPDATE tb_order
SET buyer_deleted = 1,
    update_time = datetime('now', 'localtime')
WHERE id = #{id}
  AND buyer_username = #{buyerUsername}
  AND buyer_deleted = 0

UPDATE tb_order
SET buyer_fav = 1,
    update_time = datetime('now', 'localtime')
WHERE id = #{id}
  AND buyer_username = #{buyerUsername}
  AND buyer_deleted = 0

UPDATE tb_order
SET buyer_fav = 0,
    update_time = datetime('now', 'localtime')
WHERE id = #{id}
  AND buyer_username = #{buyerUsername}
  AND buyer_deleted = 0

sql.where:
AND o.shop_id = #{filter.shopId}

    AND o.order_no = #{filter.orderNo}


    AND o.order_type = #{filter.orderType}


    AND o.order_category = #{filter.orderCategory}


    AND o.status = #{filter.status}


    AND o.receiver_name LIKE '%' || #{filter.receiverName} || '%'


    AND o.receiver_phone LIKE '%' || #{filter.receiverPhone} || '%'


    AND o.pay_type = #{filter.payType}





            AND NOT EXISTS (SELECT 1 FROM tb_refund r WHERE r.order_id = o.id)


            AND EXISTS (SELECT 1 FROM tb_refund r
                        WHERE r.order_id = o.id
                          AND r.status = #{filter.refundStatus})


            AND 1 = 0




    AND o.logistics_type = #{filter.logisticsType}


    AND o.store_name = #{filter.storeName}


    AND o.create_time >= #{filter.startDate} || ' 00:00:00'


    AND o.create_time <= #{filter.endDate} || ' 23:59:59'

AND o.buyer_username = #{filter.buyerUsername}
AND o.buyer_deleted = 0

    AND o.status = #{filter.status}


    AND o.order_no = #{filter.orderNo}
